"""Запись в прод 16.10.2026 — БД.ТЕР: обжим по AWG в одном формате и дозаполнение (владелец 16.10: «правка усилий и
высот обжима — надо заполнить все и привести к одному формату записи»).

Формат (решён 16.10): у каждого сечения из диапазона AWG контакта три значения — высота по жиле, мм; высота по
изоляции, мм; отрыв, Н. Ячейка столбца — строки «28 AWG: 0,52–0,58; 26 AWG: 0,56–0,62»: одно число или диапазон
(десятичная запятая, «–», без пробелов, без единиц и слов); отрыв — одно число (целое или с одним знаком), «Н»
дописывает экран. Уточнения, которые стояли в ячейках («UL1061 / UL1007», «макс.», «справочно…», мм² вместо AWG),
дописаны в «Источник высоты обжима» строки. Как получено каждое значение — только в журнале
«БД.ТЕР — обжим по AWG 16.10.csv» и в .md рядом; в базе — только числа.

Столбцы: «Высота обжима проводника , мм» (→ terCrimpHeight), «Высота обжима изоляции, мм» (→ terInsCrimpHeight),
«Усилие обрыва контакта, N» (→ terPullForceMin), «Источник высоты обжима».

Путь приложения: правка строки `_edit_in` (как «Изменить» в «Базе данных»), строка ищется по натуральному ключу —
артикулу контакта (REEL, иначе BAG; дефисы, пробелы и регистр не важны), никогда по ID. У каждой ячейки — старое
значение прода на 16.10: ячейка, изменённая после снимка, придёт отказом и не перепишется. Строк не создаётся и не
удаляется. Проверка: генератор (TerminalRecord + crimp_entry) читает из новой строки ровно записанные значения.

Порядок (live-data protocol, prod-reference-write):
  cd /opt/erp/app/deploy
  sudo -n docker compose --env-file /opt/erp/config/.env -f docker-compose.yml run --rm -T api python - dry   < этот файл
  sudo -n bash /opt/erp/app/deploy/erp.sh backup-now
  sudo -n docker compose ... run --rm -T api python - apply < этот файл
  sudo -n docker compose ... run --rm -T api python - dry   < этот файл   → всё «уже так»"""
