mode = (sys.argv[1] if len(sys.argv) > 1 else "dry").strip()
if mode not in ("dry", "apply"):
    raise SystemExit("режим: dry | apply")
dry = mode == "dry"
factory = build_references_uow_factory(build_engine(os.environ["ERP_DATABASE_URL"]))
now = moscow_now()
LOG = []


def norm(value):
    return re.sub(r"[\s\-‐–]", "", str(value or "")).casefold()


def s(value):
    return str(value or "").strip()


def check_reader(fields, edits):
    """The generator reads back exactly what was written, AWG by AWG."""
    record = TerminalRecord.from_fields(fields)
    for column, attr in ((COL_C, "crimp_height"), (COL_I, "ins_crimp_height"), (COL_P, "pull_force_min")):
        if column not in edits:
            continue
        stored = getattr(record, attr)
        if stored != edits[column]["new"]:
            return f"{attr}: читатель дал «{stored}»"
        for profile in parse_crimp_profiles(stored):
            if crimp_entry(stored, profile.awg_low).height != profile.height:
                return f"{attr}: {profile.awg_low} AWG читается иначе"
    return ""


with factory() as uow:
    rows = uow.tech_operations.list(tab=TechOperationTab.TERMINAL, query="", limit=100_000)
index = {}
for row in rows:
    for name in ("terArticle", "Артикул контакта (REEL)", "Артикул контакта (BAG)", "terArticleBag"):
        key = norm(row.fields.get(name))
        if key:
            index.setdefault(key, set()).add(row.id)
by_id = {row.id: row for row in rows}

counts = {}
for item in PLAN:
    key = item["key"]
    found = index.get(norm(key), set())
    status = None
    if len(found) != 1:
        status = f"отказ (строк по ключу: {len(found)})"
    else:
        row = by_id[next(iter(found))]
        todo = {column: e for column, e in item["edits"].items() if s(row.fields.get(column)) != e["new"]}
        if not todo:
            status = "уже так"
        else:
            with factory() as uow:
                try:
                    before, after = _edit_in(row.id, tuple(FieldEdit(c, e["old"], e["new"]) for c, e in todo.items()), now, uow)
                    problem = check_reader(after.fields, todo)
                    if problem:
                        raise ReferenceValidationError(problem)
                except (StaleRecordError, ReferenceValidationError, LookupError) as error:
                    status = f"отказ ({error})"
                else:
                    _audit("references.tech_record_edited", ACTOR, now, {
                        "record_id": str(before.id), "tab": before.tab.value, "fields": list(todo), "reason": REASON}, uow)
                    if not dry:
                        uow.commit()
                    status = "проверено" if dry else "записано"
    for column, e in item["edits"].items():
        LOG.append({"key": key, "field": column, "old": e["old"], "new": e["new"], "status": status})
    counts[status.split(" (")[0]] = counts.get(status.split(" (")[0], 0) + 1
    if status.startswith("отказ"):
        print(f"   {status}: «{key}»")

print("СТРОК", len(PLAN), "ЯЧЕЕК", sum(len(i["edits"]) for i in PLAN))
print("ИТОГО по строкам", json.dumps(counts, ensure_ascii=False), "(проверка, ничего не записано)" if dry else "(записано)")
print("LOG " + json.dumps(LOG, ensure_ascii=False))
